import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Full-Text Search","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/search.md","filePath":"advanced/search.md","lastUpdated":1784864016000}'),d={name:"advanced/search.md"};function o(r,e,i,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="full-text-search" tabindex="-1">Full-Text Search <a class="header-anchor" href="#full-text-search" aria-label="Permalink to &quot;Full-Text Search&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>swag2mcp includes a built-in full-text search engine (bluge) that indexes all endpoints across all specs. The LLM can search for endpoints by method, path, summary, or tag — even without knowing the endpoint ID.</p><h2 id="how-indexing-works" tabindex="-1">How indexing works <a class="header-anchor" href="#how-indexing-works" aria-label="Permalink to &quot;How indexing works&quot;">​</a></h2><p>When a spec is added or updated, every endpoint is indexed. The following fields are searchable:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>method</code></td><td>HTTP method</td><td><code>GET</code>, <code>POST</code>, <code>PUT</code></td></tr><tr><td><code>path</code></td><td>API endpoint path</td><td><code>/api/v1/users/{id}</code></td></tr><tr><td><code>summary</code></td><td>OpenAPI summary</td><td>&quot;Find pet by ID&quot;</td></tr><tr><td><code>tag</code></td><td>Endpoint category</td><td>&quot;pets&quot;, &quot;users&quot;</td></tr><tr><td><code>_all</code></td><td>All fields combined</td><td>method + path + tag + summary</td></tr></tbody></table><p>The index is rebuilt on every MCP server start. It is stored in memory for fast searches.</p><h2 id="query-syntax" tabindex="-1">Query syntax <a class="header-anchor" href="#query-syntax" aria-label="Permalink to &quot;Query syntax&quot;">​</a></h2><p>The search supports a rich query syntax for precise filtering:</p><table tabindex="0"><thead><tr><th>Example</th><th>Description</th></tr></thead><tbody><tr><td><code>pet</code></td><td>Simple text search across all fields</td></tr><tr><td><code>method:GET</code></td><td>Find all GET endpoints</td></tr><tr><td><code>tag:pets</code></td><td>Find endpoints in the &quot;pets&quot; tag</td></tr><tr><td><code>path:&quot;/api/v1/users&quot;</code></td><td>Exact path match</td></tr><tr><td><code>+method:POST +tag:pet</code></td><td>Must match both conditions</td></tr><tr><td><code>-method:DELETE</code></td><td>Exclude DELETE methods</td></tr><tr><td><code>create~</code></td><td>Fuzzy search (typo-tolerant)</td></tr><tr><td><code>cr*</code></td><td>Wildcard search</td></tr><tr><td><code>&quot;find pet&quot;</code></td><td>Phrase search</td></tr><tr><td><code>+summary:pet -method:DELETE</code></td><td>Include &quot;pet&quot; in summary, exclude DELETE</td></tr></tbody></table><h3 id="field-specific-search" tabindex="-1">Field-specific search <a class="header-anchor" href="#field-specific-search" aria-label="Permalink to &quot;Field-specific search&quot;">​</a></h3><p>You can search within specific fields using the <code>field:value</code> syntax:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>method:GET</span></span>
<span class="line"><span>tag:pets</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span>summary:&quot;find pet by status&quot;</span></span></code></pre></div><h3 id="boolean-operators" tabindex="-1">Boolean operators <a class="header-anchor" href="#boolean-operators" aria-label="Permalink to &quot;Boolean operators&quot;">​</a></h3><ul><li><code>+</code> — the term must match (AND)</li><li><code>-</code> — the term must not match (NOT)</li><li>Space between terms — OR (any term can match)</li></ul><h3 id="fuzzy-and-wildcard" tabindex="-1">Fuzzy and wildcard <a class="header-anchor" href="#fuzzy-and-wildcard" aria-label="Permalink to &quot;Fuzzy and wildcard&quot;">​</a></h3><ul><li><code>term~</code> — fuzzy search (matches similar words, handles typos)</li><li><code>te*</code> — wildcard (matches any characters)</li><li><code>te?t</code> — single character wildcard</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Find all GET requests</span></span>
<span class="line"><span>method:GET</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Find POST requests in the pet tag</span></span>
<span class="line"><span>+method:POST +tag:pet</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Find endpoints by exact path</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Find by description</span></span>
<span class="line"><span>&quot;find pet by status&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Find everything except DELETE</span></span>
<span class="line"><span>+summary:pet -method:DELETE</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Fuzzy search for &quot;create&quot; (handles typos)</span></span>
<span class="line"><span>create~</span></span></code></pre></div><h2 id="mcp-tool" tabindex="-1">MCP tool <a class="header-anchor" href="#mcp-tool" aria-label="Permalink to &quot;MCP tool&quot;">​</a></h2><p>The <code>search</code> MCP tool exposes the search engine to the LLM:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ search(query: &quot;find pet by status&quot;, limit: 5)</span></span>
<span class="line"><span>← GET /pet/findByStatus — Finds Pets by status</span></span>
<span class="line"><span>   GET /pet/{petId} — Find pet by ID</span></span></code></pre></div><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>Yes</td><td>Search query (supports structured syntax)</td></tr><tr><td><code>limit</code></td><td>Yes</td><td>Maximum results (1-50)</td></tr></tbody></table><h2 id="important-notes" tabindex="-1">Important notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to &quot;Important notes&quot;">​</a></h2><ul><li><strong>The index is in-memory</strong> — it is rebuilt every time the MCP server starts. There is no persistent index file.</li><li><strong>All fields are lowercased</strong> — searches are case-insensitive</li><li><strong>Limit is capped at 50</strong> — you cannot request more than 50 results</li><li><strong>Invalid query syntax</strong> returns a helpful error message with examples</li><li><strong>The <code>_all</code> field</strong> combines method, path, tag, and summary for simple text searches</li></ul>`,26)])])}const m=t(d,[["render",o]]);export{u as __pageData,m as default};
